struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;

    while (true) {
        if (!mm_slots_list_empty()) {
            slot = get_next_mm_slot();
            if (!slot)
                break;

            struct vm_area_struct *vma = slot->vmas;
            while (vma) {
                if (vma->vm_flags & VM_MERGEABLE) {
                    *page = get_page_from_vma(vma);
                    if (*page)
                        return get_rmap_item_from_page(*page);
                }
                vma = vma->vm_next;
            }
            cleanup_mm_slot(slot);
        } else {
            break;
        }
    }

    return NULL;
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;
    struct mm_struct *mm;
    struct page *p;

    if (!mm_list_head)
        return NULL;

    slot = get_next_mm_slot();
    if (!slot)
        return NULL;

    mm = slot->mm;
    if (!mm)
        return NULL;

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            p = find_mergeable_page(vma);
            if (p) {
                *page = p;
                return (struct rmap_item *)get_rmap_item_from_page(p);
            }
        }
    }

    cleanup_mm_slot(slot);
    return NULL;
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;
    struct mm_struct *mm;

    if (list_empty(&mm_list)) {
        return NULL;
    }

    slot = list_first_entry(&mm_list, struct mm_slot, mm_list);
    mm = slot->mm;

    for (vma = mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            if (get_mergeable_page(mm, vma, page)) {
                return get_rmap_item(*page);
            }
        }
    }

    /* No more mergeable VMAs in current mm, clean up and move to the next */
    list_del(&slot->mm_list);
    return NULL;
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;

    if (list_empty(&mm_list))
        return NULL;

    slot = list_first_entry(&mm_slot_list, struct mm_slot, mm_list);
    list_del_init(&slot->mm_list);

    for (struct vm_area_struct *vma = slot->mm->mmap; vma; vma = vma->vm_next) {
        if (vma->vm_flags & VM_MERGEABLE) {
            struct page *p = find_mergeable_page(vma, *page);
            if (p) {
                *page = p;
                return get_rmap_item(p);
            }
        }
    }

    free_mm_slot(slot);
    return get_next_rmap_item(page);
}

struct rmap_item *get_next_rmap_item(struct page **page) {
    struct mm_slot *slot;
    struct vm_area_struct *vma;

    if (!mm_list) {
        return NULL;
    }

    slot = next_mm_slot();
    while (slot) {
        vma = first_vma(slot->mm);
        while (vma) {
            if (vma->vm_flags & VM_MERGEABLE) {
                *page = find_page_in_vma(vma);
                if (*page) {
                    return get_rmap_item_from_page(*page);
                }
            }
            vma = next_vma(vma);
        }

        cleanup_mm_slot(slot);
        slot = next_mm_slot();
    }

    return NULL;
}
